cat > questions.json <<'EOF'
[
  {
    "question": "Which HTML element holds the main heading of a page?",
    "answers": [
      { "text": "<h1>", "correct": true },
      { "text": "<head>", "correct": false },
      { "text": "<header>", "correct": false },
      { "text": "<title>", "correct": false }
    ]
  },
  {
    "question": "Which HTML attribute provides alternative text for an image?",
    "answers": [
      { "text": "title", "correct": false },
      { "text": "alt", "correct": true },
      { "text": "src", "correct": false },
      { "text": "name", "correct": false }
    ]
  },
  {
    "question": "Which CSS property changes the text color of an element?",
    "answers": [
      { "text": "font-color", "correct": false },
      { "text": "text-style", "correct": false },
      { "text": "color", "correct": true },
      { "text": "foreground", "correct": false }
    ]
  },
  {
    "question": "In the CSS box model, which part lies directly between an element's content and its border?",
    "answers": [
      { "text": "Margin", "correct": false },
      { "text": "Outline", "correct": false },
      { "text": "Gap", "correct": false },
      { "text": "Padding", "correct": true }
    ]
  },
  {
    "question": "Which CSS selector targets all elements with the class \"note\"?",
    "answers": [
      { "text": ".note", "correct": true },
      { "text": "#note", "correct": false },
      { "text": "*note", "correct": false },
      { "text": "@note", "correct": false }
    ]
  },
  {
    "question": "Which keyword declares a variable in JavaScript that cannot be reassigned?",
    "answers": [
      { "text": "let", "correct": false },
      { "text": "var", "correct": false },
      { "text": "static", "correct": false },
      { "text": "const", "correct": true }
    ]
  },
  {
    "question": "What does the JavaScript expression typeof \"hello\" return?",
    "answers": [
      { "text": "\"string\"", "correct": true },
      { "text": "\"text\"", "correct": false },
      { "text": "\"char\"", "correct": false },
      { "text": "\"object\"", "correct": false }
    ]
