  {
    "question": "Which HTTP status code means the requested resource was not found?",
    "answers": [
      { "text": "200", "correct": false },
      { "text": "301", "correct": false },
      { "text": "404", "correct": true },
      { "text": "500", "correct": false }
    ]
  },
  {
    "question": "Which HTTP method is normally used to retrieve a resource without changing it?",
    "answers": [
      { "text": "POST", "correct": false },
      { "text": "GET", "correct": true },
      { "text": "DELETE", "correct": false },
      { "text": "PUT", "correct": false }
    ]
  },
  {
    "question": "Which JavaScript method selects the first element matching a CSS selector?",
    "answers": [
      { "text": "document.querySelector()", "correct": true },
      { "text": "document.getElementsByClass()", "correct": false },
      { "text": "document.findFirst()", "correct": false },
      { "text": "document.selectElement()", "correct": false }
    ]
  }
]
