node -e 'const q=JSON.parse(require("fs").readFileSync("questions.json","utf8"));console.log(q.length,q.every(x=>x.answers.length==4&&x.answers.filter(a=>a.correct).length==1),q.map(x=>x.answers.findIndex(a=>a.correct)).join(","))'
